#include <stdint.h>
typedef struct {
    volatile uint32_t CTRL;   /* offset 0x00 */
    volatile uint16_t CNT;    /* offset 0x04 */
    uint16_t          RSV0;   /* offset 0x06, padding */
    volatile uint32_t LOAD;   /* offset 0x08 */
    volatile uint8_t  FLAG;   /* offset 0x0C, sizeof = 16 */
} TMR_Type;
#define TMR0 ((TMR_Type *)0x40000400u)
/* TMR0->LOAD = 999u; writes the word at 0x40000408 */

